import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
def f(I):
    H,W=len(I),len(I[0]); out=[r[:] for r in I]; lines=[]
    for i in range(H-2):
        for j in range(W-2):
            v=I[i][j]
            if v!=0 and all(I[r][c]==v for r in range(i,i+3) for c in range(j,j+3)):
                lines.append((i+1,j+1,v))
    def on_line(r,c):
        return any(rr==r or cc==c for rr,cc,_ in lines)
    for r,c,v in lines:
        for cc in range(W): out[r][cc]=v
        for rr in range(H): out[rr][c]=v
    # crossings between two different lines go back to 0
    for a,b in [(lines[k],lines[m]) for k in range(len(lines)) for m in range(k+1,len(lines))]:
        ra,ca,_=a; rb,cb,_=b
        inter=(ra,cb),(rb,ca)
        for rr,cc in inter:
            if 0<=rr<H and 0<=cc<W and out[rr][cc]!=0: out[rr][cc]=0
    return out
print(f(I)==O)
T=f(G['Test input'])
for r in T: print(''.join(str(x) if x else '.' for x in r))
